package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import java.util.List;

/** A plan as the front end reads it: the amount with two decimals, dates yyyy-MM-dd; {@code nextDates} its first
 *  five plan dates after the sheet's today and on or before the end, comma and space separated (none while
 *  paused); {@code paused} whether it is paused now;
 *  {@code changes} its amount changes, oldest first, each as {@code <date> amount=<amount>}. */
public record PlanResponse(long id, long personId, String amount, String start, Integer every, Integer day,
        String end, int generated, String nextDates, boolean paused,
        List<String> changes) {

    public static PlanResponse from(Plan p, LocalDate today) {
        return new PlanResponse(p.id(), p.personId(), p.amount().toPlainString(), p.start().toString(), p.every(), p.day(),
                p.end().toString(), p.generated(),
                String.join(", ", p.nextDates(today, 5).stream().map(LocalDate::toString).toList()), p.paused(),
                p.changes().stream().map(c -> c.date() + " amount=" + c.amount().toPlainString()).toList());
    }
}

